/**
 * Markdown.Body: the parsed reply and its caret.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import {
  claimSlot,
  createDerived,
  markdownEndsInProse,
  markdownShallowestHeading,
  parseMarkdown,
  scope,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import MarkdownBlocks from './MarkdownBlocks'
import Text from '../structure/Text'
import type { CitationSource } from './SourceList'

export interface MarkdownBodyProps {
  /**
   * The markdown received so far.
   */
  source: string
  size: 'sm' | 'md'
  sources: CitationSource[]
  streaming: boolean
}

/** Markdown.Body: the parsed reply and its caret. */
export default function MarkdownBody(given: MarkdownBodyProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const blocks = createDerived(() =>
      parseMarkdown(props.source, { citations: props.sources.length }),
    )
    const shallowest = createDerived(() => markdownShallowestHeading(blocks.value))
    return (
      <>
        <MarkdownBlocks
          blocks={blocks.value}
          size={props.size}
          sources={props.sources}
          shallowest={shallowest.value}
          caret={props.streaming}
        />
        {props.streaming && !markdownEndsInProse(blocks.value) ? (
          <Text size={props.size}>
            {/* caret */}
            <span class={styles.caret} aria-hidden="true" />
          </Text>
        ) : null}
      </>
    )
  })
}
